<!DOCTYPE html><html lang="pt-BR"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Financeiro · Integração BI</title>
<style>
:root{--bg:#07110f;--panel:#0d1c18;--panel2:#10231e;--line:#26483f;--muted:#8ba79f;--text:#edf7f3;--green:#5dd6ad;--blue:#5b9cf6;--amber:#f3bd65;--red:#ff887e}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font-family:Inter,ui-sans-serif,system-ui,sans-serif}.layout{min-height:100vh;display:grid;grid-template-columns:240px 1fr}.sidebar{position:sticky;top:0;height:100vh;padding:26px 18px;border-right:1px solid #1e3932;background:#091713}.brand{display:flex;align-items:center;gap:11px;padding:0 8px 28px}.mark{display:grid;place-items:center;width:38px;height:38px;border-radius:12px;background:#16372e;color:var(--green)}.brand strong{font-size:14px}.nav-label{padding:0 10px;margin:16px 0 7px;color:#5f8177;font-size:10px;text-transform:uppercase;letter-spacing:.13em}.nav-item{display:flex;align-items:center;gap:10px;padding:11px 12px;border-radius:10px;color:#91aea5;text-decoration:none;font-size:13px}.nav-item.active,.nav-item:hover{background:#153129;color:#eafff7}.sidebar-foot{position:absolute;left:18px;right:18px;bottom:20px}.logout,.btn{padding:10px 14px;border:1px solid #31574c;border-radius:10px;background:#10231e;color:#d9ebe5;text-decoration:none;font-weight:650;font-size:12px;cursor:pointer}.logout{width:100%;background:transparent}.main{min-width:0;padding:34px clamp(22px,4vw,58px) 60px;background-image:radial-gradient(circle at 85% 0,#15382f 0,transparent 25%)}.top{display:flex;justify-content:space-between;gap:20px;align-items:flex-start;margin-bottom:22px}h1{margin:0;font-size:28px;letter-spacing:-.045em}.subtitle{margin:7px 0 0;color:var(--muted);font-size:13px}.filters{display:flex;gap:10px;align-items:end;flex-wrap:wrap;padding:14px;border:1px solid var(--line);border-radius:14px;background:var(--panel);margin-bottom:20px}.filters label{color:var(--muted);font-size:10px;text-transform:uppercase;letter-spacing:.08em}.filters input,.filters select{display:block;margin-top:5px;padding:9px 10px;border:1px solid #2b5046;border-radius:8px;background:#081612;color:#fff}.btn.primary{background:var(--green);border-color:var(--green);color:#062219}.cards{display:grid;grid-template-columns:repeat(4,minmax(150px,1fr));gap:12px}.metric{padding:18px;border:1px solid var(--line);border-radius:15px;background:linear-gradient(145deg,#10231e,#0b1916)}.metric span{display:block;color:var(--muted);font-size:10px;text-transform:uppercase;letter-spacing:.08em}.metric strong{display:block;margin-top:9px;font-size:23px;letter-spacing:-.04em}.metric small{display:block;margin-top:5px;color:#6e9489}.grid{display:grid;grid-template-columns:1.4fr 1fr;gap:14px;margin-top:14px}.panel{padding:18px;border:1px solid var(--line);border-radius:15px;background:var(--panel)}.panel h2{margin:0;font-size:15px}.panel p{margin:5px 0 18px;color:var(--muted);font-size:11px}.chart{height:230px;display:flex;align-items:end;gap:7px;border-bottom:1px solid #29483f;padding-top:20px}.column{flex:1;min-width:12px;height:100%;display:flex;align-items:end;position:relative}.bar{width:100%;min-height:2px;border-radius:5px 5px 0 0;background:linear-gradient(180deg,var(--green),#267b60);cursor:pointer}.bar:hover{filter:brightness(1.22)}.bar-labels{display:flex;gap:7px;margin-top:7px}.bar-labels span{flex:1;text-align:center;color:#65857c;font-size:9px}.rank{display:grid;gap:12px}.rank-head{display:flex;justify-content:space-between;gap:10px;font-size:11px}.rank-head span{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.rank-head strong{font-size:11px}.track{height:6px;margin-top:5px;border-radius:9px;background:#172d27;overflow:hidden}.fill{height:100%;border-radius:9px;background:var(--blue)}.tables{display:grid;grid-template-columns:1fr 1fr;gap:14px;margin-top:14px}table{width:100%;border-collapse:collapse}th,td{padding:10px 8px;border-bottom:1px solid #19332c;text-align:left;font-size:11px}th{color:#789a90;font-size:9px;text-transform:uppercase}.money{text-align:right;white-space:nowrap}.muted{color:var(--muted)}.empty{height:180px;display:grid;place-items:center;color:var(--muted);font-size:12px}@media(max-width:1050px){.cards{grid-template-columns:repeat(2,1fr)}.grid,.tables{grid-template-columns:1fr}}@media(max-width:760px){.layout{display:block}.sidebar{position:static;height:auto}.sidebar-foot,.nav-label{display:none}.main{padding:24px 15px}.top{display:block}.top .btn{display:inline-block;margin-top:14px}.cards{grid-template-columns:1fr 1fr}.panel{overflow:auto}}
</style></head><body><div class="layout"><aside class="sidebar"><div class="brand"><div class="mark">◆</div><strong>Integração BI</strong></div><div class="nav-label">Visão geral</div><a class="nav-item" href="{{ route('admin.dashboard') }}">◫ &nbsp; Painel</a><a class="nav-item active" href="{{ route('admin.financial') }}">▥ &nbsp; Financeiro</a><a class="nav-item" href="{{ route('admin.services') }}">◇ &nbsp; Serviços</a><a class="nav-item" href="{{ route('docs') }}" target="_blank">↗ &nbsp; Swagger API</a><div class="sidebar-foot"><form method="POST" action="{{ route('admin.logout') }}">@csrf<button class="logout">Encerrar sessão</button></form></div></aside>
