<section class="cards"><article class="metric"><span>Faturamento</span><strong>R$ {{ number_format($s['sales'],2,',','.') }}</strong><small>{{ number_format($s['sales_count'],0,',','.') }} vendas</small></article><article class="metric"><span>Ticket médio</span><strong>R$ {{ number_format($s['average_ticket'],2,',','.') }}</strong><small>Por venda não cancelada</small></article><article class="metric"><span>Contas a receber</span><strong>R$ {{ number_format($s['receivable'],2,',','.') }}</strong><small>R$ {{ number_format($s['receivable_open'],2,',','.') }} em aberto</small></article><article class="metric"><span>Contas a pagar</span><strong>R$ {{ number_format($s['payable'],2,',','.') }}</strong><small>R$ {{ number_format($s['payable_paid'],2,',','.') }} pagos</small></article><article class="metric"><span>Saldo projetado</span><strong style="color:{{ $s['balance'] >= 0 ? 'var(--green)' : 'var(--red)' }}">R$ {{ number_format($s['balance'],2,',','.') }}</strong><small>Receber menos pagar</small></article></section>
<section class="grid"><article class="panel"><h2>Faturamento diário</h2><p>Evolução das vendas não canceladas no período.</p>@if($dashboard['daily'])@php($max=max(array_column($dashboard['daily'],'total')) ?: 1)<div class="chart">@foreach($dashboard['daily'] as $row)<div class="column" title="{{ date('d/m',strtotime($row['day'])) }} · R$ {{ number_format($row['total'],2,',','.') }}"><div class="bar" style="height:{{ max(2,($row['total']/$max)*100) }}%"></div></div>@endforeach</div><div class="bar-labels">@foreach($dashboard['daily'] as $row)<span>{{ date('d/m',strtotime($row['day'])) }}</span>@endforeach</div>@else<div class="empty">Sem vendas no período selecionado.</div>@endif</article>
<article class="panel"><h2>Formas de pagamento</h2><p>Participação no valor recebido das vendas.</p>@if($dashboard['payment_methods'])@php($payMax=max(array_column($dashboard['payment_methods'],'total')) ?: 1)<div class="rank">@foreach($dashboard['payment_methods'] as $row)<div><div class="rank-head"><span>{{ $row['label'] }}</span><strong>R$ {{ number_format($row['total'],2,',','.') }}</strong></div><div class="track"><div class="fill" style="width:{{ ($row['total']/$payMax)*100 }}%"></div></div></div>@endforeach</div>@else<div class="empty">Sem formas de pagamento no período.</div>@endif</article></section>
<section class="tables"><article class="panel"><h2>Maiores contas a receber</h2><p>Clientes ordenados pelo saldo pendente.</p><table><thead><tr><th>Cliente</th><th>Títulos</th><th class="money">Em aberto</th></tr></thead><tbody>@forelse($dashboard['receivables'] as $row)<tr><td>{{ $row['customer'] }}</td><td>{{ $row['quantity'] }}</td><td class="money">R$ {{ number_format($row['open_total'],2,',','.') }}</td></tr>@empty<tr><td colspan="3" class="muted">Sem títulos no período.</td></tr>@endforelse</tbody></table></article><article class="panel"><h2>Despesas por categoria</h2><p>Concentração dos títulos a pagar.</p><table><thead><tr><th>Categoria</th><th>Lançamentos</th><th class="money">Total</th></tr></thead><tbody>@forelse($dashboard['expenses'] as $row)<tr><td>{{ $row['label'] }}</td><td>{{ $row['quantity'] }}</td><td class="money">R$ {{ number_format($row['total'],2,',','.') }}</td></tr>@empty<tr><td colspan="3" class="muted">Sem despesas no período.</td></tr>@endforelse</tbody></table></article></section><p class="muted" style="text-align:right;font-size:10px;margin-top:12px">Gerado em {{ \Carbon\Carbon::parse($dashboard['generated_at'])->format('d/m/Y H:i:s') }}</p></main></div></body></html>
